"""Format reviewer-authored dispositions after complete engineering-text reading.

No keyword classifier, test execution, or inferred PASS. Each tuple is an
independently authored obligation or bounded family of examples in the text.
"""
from pathlib import Path
import json, hashlib
H=Path(__file__).resolve().parent
W=Path('C:/Users/郑曾波/Projects/company-wiki')
rows=[json.loads(s) for s in (H/'item_ledger.jsonl').read_text(encoding='utf-8').splitlines() if s.strip()]
rows=[r for r in rows if not r['id'].startswith('WIKI-CTX-')]
new=[]
def add(path, line, promise, verdict, assessment, recommendation='保留原范围；实施/运行通过须由实际入口、配置和独立输出证据另行证明。', severity=None):
    p=W/path; lines=p.read_text(encoding='utf-8').splitlines()
    assert 1<=line<=len(lines),(path,line)
    r={'id':f'WIKI-CTX-{len(new)+1:03d}','original':{'repo':'company-wiki','path':path,'line':line},'promise':promise,
       'historical_status':'工程指南/设计或历史结果，按原文状态判定；不把设计措辞提升为已运行',
       'historical_evidence':{'source_line':lines[line-1],'sha256':hashlib.sha256(p.read_bytes()).hexdigest()},
       'current_independent_evidence':assessment,'verdict':verdict,'recommendation':recommendation,
       'scope':'engineering context: manually read prose; current static corroboration where explicitly named',
       'assessment_limit':'未执行文档内命令、未重跑历史外部服务、未验证业务正文事实；supported_scoped 仅代表所述限定命题。'}
    if severity:r['severity']=severity
    new.append(r)
def group(path, data, default='superseded'):
    for x in data:
        line,promise,assessment,*rest=x
        add(path,line,promise,rest[0] if rest else default,assessment)

