group('docs/可视化使用指南.md',[(32,'Obsidian安装、打开vault','阅读展示层说明，不是数据摄取或source资格验收。','supported_scoped'),(64,'图谱、Wikilinks、Dataview、搜索','可视化节点/命中不证明来源完整或投资结论可信；本轮无UI渲染验证。','supported_scoped'),(149,'推荐插件','历史建议，不安装、不将插件可用性当当前已验证。','historical_only'),(161,'WebClipper到inbox等待LLM','剪藏不能绕过immutable provenance/身份/许可/审核；不属于已验证canonical admission。','insufficient_evidence'),(184,'乱码/链接/图谱常见问题','演示建议不是实际已修运行结果。','historical_only'),(197,'Web浏览/搜索/产业链图谱','阅读呈现与生成writer不同；未启动server或build。','supported_scoped'),(204,'双击离线页面即可交互图谱','图谱inlineJS fetch 数据/graph_data.json，file协议是否成功需浏览器验证；本轮未验证，不能判定已成功或必失败。','insufficient_evidence'),(274,'重新build与开发模式','会写output/启动服务，不执行；旧writer边界须先澄清。'),(300,'两种展示方式对比','只是产品界面能力描述，不是生产端到端测试。','supported_scoped')])
group('docs/知识库全面审查与系统性改进计划.md',[(9,'五个尖锐发现与此前计划全部未执行','单日/日志缺席不足推出所有升级均未执行；保留历史质疑而不认可全称。','insufficient_evidence'),(19,'对照LLM Wiki理念结构差距','理念不等于来源事实准确性，合理追溯/闭环目标可保留到各owner。','historical_only'),(49,'设计意图偏离与零LLM调用','调用0不必然坏，确定性identity/date/hash应不依LLM；健康目标不是每日LLM次数。','supported_scoped'),(78,'改进报告执行断层','本轮很多helper/接线差证实这种机制风险，但不能回溯证明该日每条断言。','historical_only'),(101,'东方电缆页面过压缩导致买方不可用','历史单公司样例诊断；未重审业务事实，不扩为所有公司。','historical_only'),(115,'半导体行业page缺乏深度','历史业务案例，正文证据不在本次工程审查范围。','historical_only'),(122,'估值页没有投资判断/可信数值','后继明确投资研究移交下游，不能为修此例恢复company-wiki估值writer。'),(140,'缺少验证/压缩/淘汰熵减机制','验证和证伪合理，压缩/删除不可自动等同质量，须保护raw与独立误删评估。','supported_scoped'),(159,'零成本替代LLM导致所有失败','因果全称未被控制对照证明；错误规则/实现可坏，但LLM也需独立验证。','insufficient_evidence'),(174,'配置碎片化导致错误','本轮policy/root/doctor范围断裂有具体独立反例，可支持机制层风险而非全部旧历史数字。','supported_scoped'),(189,'全覆盖变零深度','关键需求覆盖比条目数合理；实际覆盖率应按source×driver×period定义。','supported_scoped'),(207,'三层数据架构必须执行','后继source manifest/span/export职责取代旧research三层，不重复造生产链。'),(222,'关键模块必须LLM，禁止正则替代','全称过宽；identity/hash/单位/日期/结构校验需确定性，LLM仅在证据适用场景且测误差。','contradicted'),(233,'压缩/去重/淘汰提高质量','不能据保留条数/压缩比自动推准确率，raw不可按semanticcopy自动删除。','supported_scoped'),(248,'从全覆盖转20核心公司深覆盖','可作研究抽样策略；不证明跨行业泛化，要声明样本/排除/生命周期。','supported_scoped'),(261,'废弃幽灵模块重建闭环','原则与实战一致，但已退役研究writer不可复活，闭环按source职责接下游。','supported_scoped'),(276,'统一配置单一事实来源','必要；要校验effective配置与policy一起，不能只统一配置文件名。','supported_scoped'),(283,'dashboard真实指标且LLM>50次/日','calls次数不是质量KPI，可鼓励无用/重复调用；改为用户journey/错误/准确性测量。','contradicted'),(298,'文档→代码转化和阶段验证','需保留原义务/缩范围/后继未做，不能再次只验文件/卡片存在。','supported_scoped'),(310,'P0本周/P1两周/P2一月/P3持续排程','旧期限已过不等于每条实施失败；后继scope/移交优先，未获执行证据部分历史处理。','historical_only'),(342,'文档多但改进失败的结语','作为问题陈述不反转成产品通过；本轮区分真实修复与误扩通过。','supported_scoped')])
